<body>
    <div class="container">
        <div class="title">أدخل الرمز</div>
        <div class="subtitle">لقد أرسلنا رمزًا مكوّنًا من 6 أرقام إلى +966 55 123 4567</div>
        <div class="code-container">
            <input type="text" maxlength="1" class="code-box" id="code1">
            <input type="text" maxlength="1" class="code-box" id="code2">
            <input type="text" maxlength="1" class="code-box" id="code3">
            <input type="text" maxlength="1" class="code-box" id="code4">
            <input type="text" maxlength="1" class="code-box" id="code5">
            <input type="text" maxlength="1" class="code-box" id="code6">
        </div>
        <div class="countdown">إعادة الإرسال خلال <span id="timer">0:45</span></div>
        <button class="verify-btn" id="verifyBtn">تحقق</button>
    </div>

    <script>
        const boxes = document.querySelectorAll('.code-box');
        const timerEl = document.getElementById('timer');
        const verifyBtn = document.getElementById('verifyBtn');
        let seconds = 45;

        // Move to next box automatically
        boxes.forEach((box, index) => {
            box.addEventListener('input', () => {
                if (box.value.length === 1 && index < boxes.length - 1) {
                    boxes[index + 1].focus();
                }
                checkCodeComplete();
            });

            box.addEventListener('keydown', (e) => {
                if (e.key === 'Backspace' && index > 0 && !box.value) {
                    boxes[index - 1].focus();
                }
            });
        });

        function checkCodeComplete() {
            const code = Array.from(boxes).every(b => b.value.length === 1);
            verifyBtn.disabled = !code;
        }

        // Countdown timer
        const countdown = setInterval(() => {
            seconds--;
            const mins = Math.floor(seconds / 60);
            const secs = seconds % 60;
            timerEl.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;

            if (seconds <= 0) {
                clearInterval(countdown);
                timerEl.textContent = 'يمكنك إعادة الإرسال الآن';
                timerEl.style.color = '#28a745';
            }
        }, 1000);
    </script>
</body>
